model:
rachana: 1
sutra: lei-mapping
version: 1
description: 
match: { kind: lei-mapping, priority: 10 }
title: { pill: "GLEIF · Identifier", id: "$.IDENTIFIER", with: "$.ENTITY_NAME" }
strip:
  - { label: "Type", bind: "$.TYPE", emphasis: true }
  - { label: "LEI", bind: "link($.ENTITY_LEI, 'lei-entity')" }
  - { label: "Entity", bind: "$.ENTITY_NAME" }
  - { label: "Country", bind: "link($.COUNTRY, 'lei-country')" }
panels:
  - id: mapping
    kind: kv
    title: "The mapping"
    key: "F2"
    columns:
      - { label: "Identifier", bind: "$.IDENTIFIER" }
      - { label: "Type", bind: "$.TYPE == 'BIC' ? 'BIC (business identifier code, with SWIFT)' : ($.TYPE == 'ISIN' ? 'ISIN (securities identifier, with ANNA: the issuer)' : 'MIC (market identifier code: the operator)')" }
      - { label: "Maps to", bind: "link($.ENTITY_LEI, 'lei-entity', $.ENTITY_NAME)" }
      - { label: "Ownership group", bind: "link($.LEI_GROUP, 'lei-group')" }
      - { label: "ISINs of the issuer", bind: "$.ISIN_COUNT", fmt: "entities0" }
      - { label: "Mapping file", bind: "$.MAPPING_FILE" }
  - id: entity
    kind: kv
    title: "The entity"
    area: right
    columns:
      - { label: "Legal name", bind: "link($src.LEI, 'lei-entity', $src.NAME)" }
      - { label: "LEI", bind: "$src.LEI" }
      - { label: "Legal form", bind: "$src.LEGAL_FORM" }
      - { label: "Category", bind: "nonblank($src.CATEGORY, 'General')" }
      - { label: "Jurisdiction", bind: "nonblank($src.JURISDICTION, $src.LEI_COUNTRY)" }
      - { label: "Country", bind: "link($src.LEI_COUNTRY, 'lei-country', $src.COUNTRY_NAME)" }
      - { label: "City", bind: "$src.LEGAL_CITY" }
      - { label: "Registered as", bind: "$src.REGISTERED_AS" }
      - { label: "Entity status", bind: "$src.ENTITY_STATUS" }
      - { label: "Registration", bind: "$src.REGISTRATION_STATUS == 'LAPSED' ? 'LAPSED: renewal failed' : $src.REGISTRATION_STATUS", tone: "status" }
      - { label: "Next renewal", bind: "$src.NEXT_RENEWAL", fmt: "date" }
      - { label: "Managing LOU", bind: "$src.MANAGING_LOU" }
      - { label: "Direct parent", bind: "link($src.DIRECT_PARENT, 'lei-entity')" }
      - { label: "Ownership group", bind: "link($src.LEI_GROUP, 'lei-group')" }
      - { label: "Children in the pack", bind: "$src.CHILD_COUNT", fmt: "entities0" }
      - { label: "BICs", bind: "$src.BICS" }
      - { label: "ISINs (GLEIF mapping)", bind: "$src.ISIN_COUNT", fmt: "entities0" }
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
keys: { F5: "link($.ENTITY_LEI, 'lei-entity', 'Entity')", F9: "raw" }
